const b = $('Build Payload').first().json;
const u = $('Update Keys').first().json;
const body = u.body || {};
const langs = ($input.first().json.languages || []).map(function (l) { return l.lang_iso; });
return [{ json: { sent: b.count, skipped_existing_description: b.skipped_existing_description, not_found: b.not_found, status: u.statusCode, updated: (body.keys || []).length, errors: body.errors || body.error || null, languages: langs } }];
